"""User-local shims management, activation, and state tracking."""

import json
import os
import stat
from typing import Dict, List, Optional, Tuple

from .config import get_shims_dir, get_state_dir, atomic_write_file
from .errors import VersionManagerError, UnknownToolError, ExitCode
from .providers.registry import ProviderRegistry, get_default_registry


SHIM_TEMPLATE = """#!/usr/bin/env bash
# eselect-version-manager shim for {command}
# Generated by eselect version-manager shims install
set -e

# Resolve dispatcher path
DISPATCHER="${{ESELECT_VM_DISPATCHER:-/usr/libexec/eselect-version-manager/dispatcher}}"
if [[ ! -x "${{DISPATCHER}}" ]]; then
    if command -v eselect-version-manager >/dev/null 2>&1; then
        DISPATCHER="$(command -v eselect-version-manager)"
    elif command -v dispatcher >/dev/null 2>&1; then
        DISPATCHER="$(command -v dispatcher)"
    fi
fi

if [[ ! -x "${{DISPATCHER}}" ]]; then
    echo "eselect-version-manager: dispatcher not found at '${{DISPATCHER}}'" >&2
    exit 1
fi

exec "${{DISPATCHER}}" dispatch "{command}" "$@"
"""


def get_disabled_shims_file() -> str:
    return os.path.join(get_state_dir(), "disabled_shims.json")


def load_disabled_shims() -> set:
    state_file = get_disabled_shims_file()
    if not os.path.exists(state_file):
        return set()
    try:
        with open(state_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            return set(data.get("disabled", []))
    except Exception:
        return set()


def save_disabled_shims(disabled: set) -> None:
    state_file = get_disabled_shims_file()
    try:
        atomic_write_file(state_file, json.dumps({"disabled": sorted(list(disabled))}, indent=2))
    except Exception as e:
        raise VersionManagerError(
            f"failed to save shim state to '{state_file}': {e}",
            exit_code=ExitCode.GENERAL_ERROR,
            details={"state_file": state_file, "error": str(e)}
        )


def is_shim_disabled(tool_or_command: str) -> bool:
    disabled = load_disabled_shims()
    return tool_or_command in disabled


class ShimManager:
    """Manages creation, uninstallation, enabling, and disabling of user-local shims."""

    def __init__(self, registry: Optional[ProviderRegistry] = None, shims_dir: Optional[str] = None):
        self.registry = registry or get_default_registry()
        self.shims_dir = shims_dir or get_shims_dir()

    def get_commands_for_tool(self, tool_name: str) -> List[str]:
        provider = self.registry.get_provider(tool_name)
        return provider.commands

    def install(self, tools_or_commands: List[str]) -> List[str]:
        """
        Install executable shims in $HOME/.local/bin/eselect-version-manager/shims/.
        Ensures shims are marked executable and enabled.
        Rejects tools not supported by any registered provider.
        """
        os.makedirs(self.shims_dir, exist_ok=True)
        installed = []
        disabled_set = load_disabled_shims()

        for item in tools_or_commands:
            provider = self.registry.find_provider_for_command(item)
            if not provider:
                raise UnknownToolError(
                    item,
                    details={
                        "available_tools": ", ".join(self.registry.list_tools()),
                        "suggestion": f"create a provider configuration in /etc/eselect/version-manager/providers.d/{item}.conf or ~/.config/eselect/version-manager/providers.d/{item}.conf"
                    }
                )
            cmds = provider.commands if item == provider.name else [item]

            for cmd in cmds:
                shim_path = os.path.join(self.shims_dir, cmd)
                content = SHIM_TEMPLATE.format(command=cmd)
                atomic_write_file(shim_path, content, mode=0o755)
                # Ensure enabled upon install
                disabled_set.discard(cmd)
                disabled_set.discard(provider.name)
                installed.append(cmd)

        save_disabled_shims(disabled_set)
        return installed

    def enable(self, tools_or_commands: List[str]) -> List[str]:
        """Enable previously disabled shims."""
        disabled_set = load_disabled_shims()
        enabled = []

        for item in tools_or_commands:
            provider = self.registry.find_provider_for_command(item)
            if not provider:
                raise UnknownToolError(
                    item,
                    details={"available_tools": ", ".join(self.registry.list_tools())}
                )
            cmds = provider.commands if item == provider.name else [item]
            for cmd in cmds:
                disabled_set.discard(cmd)
                disabled_set.discard(provider.name)
                enabled.append(cmd)

        save_disabled_shims(disabled_set)
        return enabled

    def disable(self, tools_or_commands: List[str]) -> List[str]:
        """
        Disable shims without deleting them or modifying user selections.
        When disabled, shims delegate directly to system executables.
        """
        disabled_set = load_disabled_shims()
        disabled = []

        for item in tools_or_commands:
            provider = self.registry.find_provider_for_command(item)
            if not provider:
                raise UnknownToolError(
                    item,
                    details={"available_tools": ", ".join(self.registry.list_tools())}
                )
            cmds = provider.commands if item == provider.name else [item]
            for cmd in cmds:
                disabled_set.add(cmd)
                disabled.append(cmd)
            disabled_set.add(provider.name)

        save_disabled_shims(disabled_set)
        return disabled

    def uninstall(self, tools_or_commands: List[str]) -> List[str]:
        """Remove shim files from shims directory."""
        uninstalled = []
        disabled_set = load_disabled_shims()

        for item in tools_or_commands:
            provider = self.registry.find_provider_for_command(item)
            cmds = provider.commands if provider and item == provider.name else [item]
            for cmd in cmds:
                shim_path = os.path.join(self.shims_dir, cmd)
                if os.path.exists(shim_path):
                    try:
                        os.remove(shim_path)
                        uninstalled.append(cmd)
                    except OSError:
                        pass
                disabled_set.discard(cmd)

        save_disabled_shims(disabled_set)
        return uninstalled

    def list_shims(self) -> List[Dict[str, str]]:
        """List all installed shims and their status."""
        if not os.path.isdir(self.shims_dir):
            return []

        disabled_set = load_disabled_shims()
        results = []

        for entry in sorted(os.listdir(self.shims_dir)):
            shim_path = os.path.join(self.shims_dir, entry)
            if not os.path.isfile(shim_path):
                continue

            provider = self.registry.find_provider_for_command(entry)
            tool_name = provider.name if provider else "(custom)"
            is_disabled = (entry in disabled_set) or (tool_name in disabled_set)

            results.append({
                "command": entry,
                "tool": tool_name,
                "provider": provider.package_atom if provider else "(unknown)",
                "status": "disabled" if is_disabled else "enabled",
                "path": shim_path,
            })

        return results

    def get_activation_env(self) -> str:
        """Return shell snippet to add shims directory to PATH."""
        return f'export PATH="{self.shims_dir}:$PATH"'
